// Extract file_name from incoming webhook body
const body = $input.item.json.body || $input.item.json;
const fileName = body.file_name;

if (!fileName) {
  throw new Error('No file_name in payload. Keys: ' + Object.keys(body).join(', '));
}

return {
  json: { file_name: fileName }
};

// Call Supabase RPC endpoint to crosslink entries
const fileName = $input.item.json.file_name;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/crosslink_entry',
  headers: {
    'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24',
    'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24',
    'Content-Type': 'application/json'
  },
  body: {
    p_file_name: fileName
  },
  json: true
});

return {
  json: response
};

// Trigger WF-03 notification with crosslink data
// Also fetch the entry's tags, entities, and summary for the notification
const rpcResult = $input.item.json;

// Fetch the entry details for the notification
const url = `https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/metadata?id=eq.${rpcResult.entry_id}&select=file_name,tags,entities,summary`;
const entry = await this.helpers.httpRequest({
  method: 'GET',
  url: url,
  headers: {
    'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24',
    'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24'
  },
  json: true
});
const entryData = (entry && entry[0]) || {};

// Fire WF-03 webhook
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://n8n-docker-t9sr.onrender.com/webhook/wf03-crosslink-notify',
  headers: { 'Content-Type': 'application/json' },
  body: {
    entry_id: rpcResult.entry_id,
    file_name: entryData.file_name || '',
    related_ids: rpcResult.related_ids || [],
    related_count: rpcResult.related_count || 0,
    tags: entryData.tags || [],
    entities: entryData.entities || [],
    summary: entryData.summary || ''
  },
  json: true
});

return {
  json: {
    ...rpcResult,
    wf03_triggered: true
  }
};
